    public String parseTransactionStatus(String status, String type)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "deposit", new HashMap<String, Object>() {{
                put( "1", "pending" );
                put( "2", "ok" );
                put( "3", "failed" );
                put( "4", "canceled" );
                put( "5", "transfer" );
            }} );
            put( "withdrawal", new HashMap<String, Object>() {{
                put( "1", "pending" );
                put( "2", "canceled" );
                put( "3", "failed" );
                put( "4", "ok" );
            }} );
        }};
        return this.safeString(this.safeDict(statuses, ((String)type), new HashMap<String, Object>() {{}}), status, status);
    }

    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        // fetchDeposits (private)
        //
        //      {
        //          "insertTime":1649012310000,
        //          "amount":9.00000000000000000000,
        //          "address":"TYASr5UV6HEcXatwdFQfmLVUqQQQMUxHLS",
        //          "networkName":"trc20",
        //          "txId":"081e4e9351dd0274922168da5f2d14ea6c495b1c3b440244f4a6dd9fe196bf2b",
        //          "coin":"usdt",
        //          "status":"2"
        //      }
        //
        //
        // fetchWithdrawals (private)
        //
        //      {
        //          "amount":2.00000000000000000000,
        //          "address":"TBjrW5JHDyPZjFc5nrRMhRWUDaJmhGhmD6",
        //          "fee":1.00000000000000000000,
        //          "networkName":"trc20",
        //          "coid":"usdt",
        //          "transferType":"数字资产提现",
        //          "txId":"47eeee2763ad49b8817524dacfa7d092fb58f8b0ab7e5d25473314df1a793c3d",
        //          "id":1902194,
        //          "applyTime":1649014002000,
        //          "status":"4"
        //      }
        //
        String id = this.safeString(transaction, "id");
        String type = null;
        if (java.util.Objects.equals(id, null))
        {
            type = "deposit";
        } else
        {
            type = "withdrawal";
        }
        String txid = this.safeString(transaction, "txId");
        Long timestamp = (Long) this.safeInteger2(transaction, "insertTime", "applyTime");
        String address = this.safeString(transaction, "address");
        String addressFrom = null;
        String addressTo = null;
        if (java.util.Objects.equals(type, "deposit"))
        {
            addressFrom = address;
        } else
        {
            addressTo = address;
        }
        Double amount = this.safeNumber(transaction, "amount");
        String currencyId = this.safeString2(transaction, "coin", "coid");
        String code = this.safeCurrencyCode(currencyId, currency);
        String status = this.parseTransactionStatus(this.safeString(transaction, "status"), type);
        Map<String, Object> fee = null;
        Double feeCost = this.safeNumber(transaction, "fee");
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Double finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "cost", finalFeeCost );
                put( "currency", code );
            }};
        }
        final String finalId = id;
        final String finalAddressTo = addressTo;
        final String finalAddressFrom = addressFrom;
        final String finalType = type;
        final String finalStatus = status;
        final Map<String, Object> finalFee = fee;
        return new HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", finalId );
            put( "txid", txid );
            put( "timestamp", timestamp );
            put( "datetime", Lbank.this.iso8601(timestamp) );
            put( "network", Lbank.this.networkIdToCode(Lbank.this.safeString(transaction, "networkName"), code) );
            put( "address", address );
            put( "addressTo", finalAddressTo );
            put( "addressFrom", finalAddressFrom );
            put( "tag", null );
            put( "tagTo", null );
            put( "tagFrom", null );
            put( "type", finalType );
            put( "amount", amount );
            put( "currency", code );
            put( "status", finalStatus );
            put( "updated", null );
            put( "comment", null );
            put( "internal", (java.util.Objects.equals(finalStatus, "transfer")) );
            put( "fee", finalFee );
        }};
    }
    public Object parseTransaction(Map<String, Object> transaction, Object... optionalArgs)
    {
        return this.parseTransaction(transaction, Helpers.getArgMap(optionalArgs, 0, null));
    }

